internal static class FirstUseRegression {
 static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
 static void CopyDir(string source,string target,bool includeBinding){Directory.CreateDirectory(target);foreach(string d in Directory.GetDirectories(source,"*",SearchOption.TopDirectoryOnly))CopyDir(d,Path.Combine(target,Path.GetFileName(d)),includeBinding);foreach(string f in Directory.GetFiles(source,"*",SearchOption.TopDirectoryOnly)){if(!includeBinding&&Path.GetFileName(f)=="data-location.json")continue;File.Copy(f,Path.Combine(target,Path.GetFileName(f)),false);}}
 static void CopyTree(string source,string target,bool includeBinding=false){Directory.CreateDirectory(target);foreach(string name in new[]{"build","rules"}){string from=Path.Combine(source,name);if(Directory.Exists(from))CopyDir(from,Path.Combine(target,name),includeBinding);}}
 static string HashTree(string root){return DataMigration.Fingerprint(root,()=>{});}
 internal static int Run(string revision,string output){try{
  string packageProgram=Common.AppRoot;string id="fu-"+Guid.NewGuid().ToString("N").Substring(0,8);string root=Path.Combine(Common.AppRoot,"tests",id);Directory.CreateDirectory(root);
  string program=Path.Combine(root,"中文 空间"),parent=Path.Combine(program,"tests","数据 新建"),binding;
  string failedProgram=Path.Combine(root,"清理 程序");CopyTree(revision,failedProgram);string failedParent=Path.Combine(failedProgram,"tests","清理 数据");Directory.CreateDirectory(failedParent);Common.AppRoot=failedProgram;
  FirstUseSetup.TestFailurePoint=name=>{if(name=="before-binding-publish")throw new IOException("isolated failure injection");};bool injectedFailure=false;try{FirstUseSetup.InitializeNew(failedParent,failedProgram,Path.Combine(failedProgram,"build","data-location.json"));}catch(IOException){injectedFailure=true;}finally{FirstUseSetup.TestFailurePoint=null;}Require(injectedFailure&&!Directory.GetFileSystemEntries(failedParent).Any()&&!File.Exists(Path.Combine(failedProgram,"build","data-location.json")),"初始化失败没有清理本任务临时/未提交数据");
  CopyTree(revision,program);Directory.CreateDirectory(parent);binding=Path.Combine(program,"build","data-location.json");
  Common.AppRoot=program;Common.Root=program;
  Require(!FirstUseSetup.InitializeNew(null,program,binding),"取消/空选择不应创建任何文件");Require(!Directory.GetFileSystemEntries(parent).Any(),"取消选择写入了文件");
