  var loc=DataLocation.LoadBound(binding);DataLocation.ValidateStore(loc,false);Require(loc.DataRoot==Path.Combine(parent,"LocalWallpaper","Data"),"数据位置未绑定到用户所选位置");Require(File.Exists(Path.Combine(loc.DataRoot,"data","catalog.json")),"空登记缺失");
  var catalog=DataLocation.ReadSmall<LibraryDocument>(Path.Combine(loc.DataRoot,"data","catalog.json"));Require(catalog.Items.Count==0,"新用户登记不是明确空库");var settings=DataLocation.ReadSmall<AppSettings>(Path.Combine(loc.DataRoot,"data","settings.json"),16384);Require(settings.Muted&&settings.Volume==30,"首次设置默认值不符合约定");
  string before=HashTree(loc.DataRoot);bool duplicateRefused=false;try{FirstUseSetup.InitializeNew(parent,program,binding);}catch(InvalidOperationException){duplicateRefused=true;}Require(duplicateRefused&&HashTree(loc.DataRoot)==before,"重复初始化覆盖已有库");
  string nonEmpty=Path.Combine(program,"tests","有文件");Directory.CreateDirectory(nonEmpty);File.WriteAllText(Path.Combine(nonEmpty,"keep.txt"),"keep");string nonEmptyProgram=Path.Combine(root,"其他 程序");CopyTree(revision,nonEmptyProgram);string nonEmptyBinding=Path.Combine(nonEmptyProgram,"build","data-location.json");Require(FirstUseSetup.InitializeNew(nonEmpty,nonEmptyProgram,nonEmptyBinding),"包含其他文件的父目录应允许创建独立LocalWallpaper子目录");Require(File.ReadAllText(Path.Combine(nonEmpty,"keep.txt"))=="keep"&&File.Exists(Path.Combine(nonEmpty,"LocalWallpaper","Data","data","catalog.json")),"新建目录改写了其他文件或空库缺失");bool targetCollision=false;try{FirstUseSetup.InitializeNew(nonEmpty,nonEmptyProgram,nonEmptyBinding);}catch(InvalidOperationException){targetCollision=true;}catch(IOException){targetCollision=true;}Require(targetCollision&&File.ReadAllText(Path.Combine(nonEmpty,"keep.txt"))=="keep","已有LocalWallpaper目标未被安全拒绝");
  string deniedParent=Path.Combine(program,"tests","不可写");Directory.CreateDirectory(deniedParent);var deniedInfo=new DirectoryInfo(deniedParent);var deniedAcl=deniedInfo.GetAccessControl();var deniedRule=new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.CreateFiles|FileSystemRights.CreateDirectories|FileSystemRights.WriteAttributes|FileSystemRights.WriteExtendedAttributes,AccessControlType.Deny);deniedAcl.AddAccessRule(deniedRule);deniedInfo.SetAccessControl(deniedAcl);bool writeDenied=false;try{try{FirstUseSetup.InitializeNew(deniedParent,failedProgram,Path.Combine(failedProgram,"build","data-location.json"));}catch(UnauthorizedAccessException){writeDenied=true;}catch(IOException){writeDenied=true;}Require(writeDenied,"不可写数据位置未安全拒绝");}finally{deniedAcl.RemoveAccessRuleSpecific(deniedRule);deniedInfo.SetAccessControl(deniedAcl);}Require(Directory.GetFileSystemEntries(deniedParent).Length==0&&!File.Exists(Path.Combine(failedProgram,"build","data-location.json")),"不可写位置失败后留下半成品");
  string releaseHash=Common.Hash(VersionStore.ReleasePath(program));VersionStore.VerifyRelease(program,releaseHash,1);string moved=Path.Combine(root,"移动后的版本 中文 空格");CopyTree(program,moved,true);VersionStore.VerifyRelease(moved,Common.Hash(VersionStore.ReleasePath(moved)),1);var movedBinding=DataLocation.ReadBinding(Path.Combine(moved,"build","data-location.json"));Require(DataLocation.Same(movedBinding.DataRoot,loc.DataRoot),"移动程序后丢失用户数据位置关系");
  Environment.SetEnvironmentVariable("LOCALWALLPAPER_TEST_CONTROL",Path.Combine(parent,"LocalWallpaper","Control"));Environment.SetEnvironmentVariable("LOCALWALLPAPER_TEST_BINDING",binding);Common.AppRoot=program;DataLocation.Initialize();Require(DataLocation.Ready&&DataLocation.Same(Common.Root,loc.DataRoot),"已有库启动验证失败");Require(HashTree(loc.DataRoot)==before,"已有库启动改写了新用户数据");
  string nextProgram=Path.Combine(program,"tests","版本切换 中文 空格");CopyTree(revision,nextProgram);var switched=VersionStore.Switch(nextProgram,false);Require(DataLocation.Same(switched.DataRoot,loc.DataRoot)&&DataLocation.Same(switched.ActiveRoot,nextProgram),"首次切换没有保留数据根");var targetBinding=DataLocation.ReadBinding(Path.Combine(nextProgram,"build","data-location.json"));Require(targetBinding.StoreId==loc.StoreId&&DataLocation.Same(targetBinding.DataRoot,loc.DataRoot),"切换前未为无绑定目标版本建立同源绑定");var rolled=VersionStore.Switch(program,true);Require(DataLocation.Same(rolled.ActiveRoot,program)&&DataLocation.Same(rolled.DataRoot,loc.DataRoot),"兼容回退未回到旧程序或改变数据根");Require(HashTree(loc.DataRoot)==before,"程序切换/回退更改了用户数据");
  var original=DataLocation.ReadSmall<Deployment>(Path.Combine(Environment.GetEnvironmentVariable("LOCALWALLPAPER_TEST_CONTROL"),"deployment.json"));var broken=new Deployment{SchemaVersion=1,DataFormat=1,StoreId=original.StoreId,DataRoot=Path.Combine(program,"tests","missing-data"),ActiveRoot=program,ReleaseSha256=original.ReleaseSha256};Common.ReplaceJson(DataLocation.ConfigPath,broken);bool missingDataRefused=false;try{DataLocation.Initialize();}catch{missingDataRefused=true;}Require(missingDataRefused,"已有配置指向丢失数据时未拒绝启动");Require(HashTree(loc.DataRoot)==before,"丢失数据检查改写了已有库");Common.ReplaceJson(DataLocation.ConfigPath,original);
  File.WriteAllText(DataLocation.ConfigPath,"{broken-json");bool corruptConfigRefused=false;try{DataLocation.Initialize();}catch{corruptConfigRefused=true;}Require(corruptConfigRefused&&HashTree(loc.DataRoot)==before,"损坏的数据配置未安全拒绝");Common.ReplaceJson(DataLocation.ConfigPath,original);
  var unsupported=new Deployment{SchemaVersion=1,DataFormat=99,StoreId=original.StoreId,DataRoot=original.DataRoot,ActiveRoot=program,ReleaseSha256=original.ReleaseSha256};Common.ReplaceJson(DataLocation.ConfigPath,unsupported);bool unsupportedDataRefused=false;try{DataLocation.Initialize();}catch{unsupportedDataRefused=true;}Require(unsupportedDataRefused&&HashTree(loc.DataRoot)==before,"不兼容数据格式未安全拒绝");Common.ReplaceJson(DataLocation.ConfigPath,original);
  string bindingPath=Path.Combine(program,"build","data-location.json");var originalBinding=DataLocation.ReadBinding(bindingPath);var conflictingBinding=new LocationBinding{SchemaVersion=1,ControlRoot=originalBinding.ControlRoot,DataRoot=Path.Combine(program,"build"),StoreId=originalBinding.StoreId};Common.ReplaceJson(bindingPath,conflictingBinding);bool conflictingBindingRefused=false;try{DataLocation.Initialize();}catch{conflictingBindingRefused=true;}Require(conflictingBindingRefused&&HashTree(loc.DataRoot)==before,"冲突的数据绑定未安全拒绝");Common.ReplaceJson(bindingPath,originalBinding);
  string leasePath=Path.Combine(loc.DataRoot,".writer.lock");using(var lockHolder=new FileStream(leasePath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){bool leaseConflictRefused=false;try{using(var competing=new DataLease(loc.DataRoot)){} }catch(IOException){leaseConflictRefused=true;}Require(leaseConflictRefused,"已有写入占用时未拒绝第二个写入者");}if(File.Exists(leasePath))File.Delete(leasePath);Require(HashTree(loc.DataRoot)==before,"写入占用检查改写了已有隔离库");
  bool corruptReleaseRefused=false;string bad=Path.Combine(root,"格式不兼容 中文");CopyTree(program,bad);string rel=VersionStore.ReleasePath(bad);File.WriteAllText(rel,"{\"SchemaVersion\":99,\"MinDataFormat\":1,\"MaxDataFormat\":1,\"Files\":[]}");try{VersionStore.VerifyRelease(bad,Common.Hash(rel),1);}catch(InvalidDataException){corruptReleaseRefused=true;}Require(corruptReleaseRefused,"不兼容程序清单未拒绝");
  Common.AppRoot=packageProgram;Common.Root=packageProgram;string reopenParent=Path.Combine(packageProgram,"tests","reopen-data");Directory.CreateDirectory(reopenParent);string reopenBinding=Path.Combine(packageProgram,"build","data-location.json");Require(!File.Exists(reopenBinding),"Package copy unexpectedly already has a binding");Require(FirstUseSetup.InitializeNew(reopenParent,packageProgram,reopenBinding),"Package-root isolated initialization failed");var reopenDeployment=DataLocation.LoadBound(reopenBinding);DataLocation.ValidateStore(reopenDeployment,false);
  var result=new{passed=true,scope="isolated first-use/data-location/package verification",newUserExplicitInitialization=true,cancelledChoiceNoWrite=true,failedInitializationCleaned=true,emptyCatalog=true,settingsMuted=true,existingLibraryBinding=true,bindingPath=binding,dataRoot=loc.DataRoot,programRoot=program,storeId=loc.StoreId,dataFormat=loc.DataFormat,reopenBindingPath=reopenBinding,reopenDataRoot=reopenDeployment.DataRoot,reopenStoreId=reopenDeployment.StoreId,reopenDataFormat=reopenDeployment.DataFormat,repeatedInitializationRefused=true,nonEmptyDestinationPreserved=true,unwritableDestinationRefusedAndCleaned=true,existingConfiguredButMissingDataRefused=true,corruptDeploymentConfigRefused=corruptConfigRefused,unsupportedDataFormatRefused=unsupportedDataRefused,conflictingProgramDataBindingRefused=conflictingBindingRefused,activeWriterLeaseConflictRefused=true,programPathChangedWithChineseAndSpaces=true,packageVersionSwitchCreatedMissingBinding=true,compatibleRollbackPreservedData=true,incompatibleReleaseRejected=true,formalDataReadOrWritten=false,formalCwpCopied=false,playerStarted=false,desktopChanged=false,systemConfigurationChanged=false,systemStartupChanged=false,testRoot=root};
  Common.SaveNew(output,result);return 0;
 }catch(Exception ex){try{Directory.CreateDirectory(Path.GetDirectoryName(output));Common.SaveNew(output,new{passed=false,error=FaultSafety.Text(ex.GetType().Name+"："+ex.Message),formalDataReadOrWritten=false,playerStarted=false,desktopChanged=false,systemConfigurationChanged=false});}catch{}return 1;}finally{Environment.SetEnvironmentVariable("LOCALWALLPAPER_TEST_CONTROL",null);Environment.SetEnvironmentVariable("LOCALWALLPAPER_TEST_BINDING",null);}}
